// 葡语/误分类路径：正文已被非误分类目录覆盖时移入 quarantine
import fs from "fs";
import path from "path";
import os from "os";

const DRY = process.argv.includes("--dry");
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const QUAR = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out",
  "dedupe-quarantine",
  new Date().toISOString().replace(/[:.]/g, "-")
);
const BAD_DIR = /padrão|estrutura de|projeto de|padrão técnico|technical_pattern/i;

function bodyOf(raw) {
  return raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g, "").trim();
}

const cnBodies = [];
const foreign = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && e.name !== ".overview.md" && !e.name.startsWith(".")) {
      const rel = path.relative(MEM, p).replace(/\\/g, "/");
      const raw = fs.readFileSync(p, "utf8");
      const body = bodyOf(raw);
      if (BAD_DIR.test(rel)) foreign.push({ rel, abs: p, body });
      else cnBodies.push(body);
    }
  }
}
walk(MEM);

function needles(body) {
  const raw = body.match(/[\u4e00-\u9fffA-Za-z0-9_./:-]{14,}/g) || [];
  return [...new Set(raw)].sort((a, b) => b.length - a.length).slice(0, 6);
}

function covered(body) {
  const nd = needles(body);
  for (const cn of cnBodies) {
    let hits = 0;
    for (const n of nd) {
      if (n.length >= 14 && cn.includes(n)) hits++;
      if (hits >= 2) return true;
    }
    const long = nd.find((n) => n.length >= 24 && cn.includes(n));
    if (long) return true;
  }
  return false;
}

const actions = [];
let moved = 0;
for (const f of foreign) {
  if (f.body.length < 40) continue;
  if (!covered(f.body)) continue;
  actions.push({ remove: f.rel });
  if (!DRY) {
    const dest = path.join(QUAR, f.rel);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.renameSync(f.abs, dest);
    moved++;
  }
}

const logPath = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out",
  "foreign-quarantine-log.json"
);
fs.writeFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), dry: DRY, moved, actions }, null, 2));
console.log(DRY ? "DRY" : "APPLIED", "candidates", actions.length, "moved", moved);
if (!DRY && moved) console.log("Quarantine:", QUAR);

