// 葡语误分类：仅当同名 slug 在非误分类目录已有副本时移走（勿删唯一副本）
import fs from "fs";
import path from "path";
import os from "os";

const DRY = process.argv.includes("--dry");
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const QUAR = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out",
  "dedupe-quarantine",
  new Date().toISOString().replace(/[:.]/g, "-")
);
const BAD_DIR = /padrão|estrutura de|projeto de|padrão técnico|technical_pattern/i;

const byBase = new Map();
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && e.name !== ".overview.md" && !e.name.startsWith(".")) {
      const rel = path.relative(MEM, p).replace(/\\/g, "/");
      const base = path.basename(p, ".md").toLowerCase();
      if (!byBase.has(base)) byBase.set(base, []);
      byBase.get(base).push({ rel, abs: p, foreign: BAD_DIR.test(rel) });
    }
  }
}
walk(MEM);

function bodyOf(abs) {
  return fs
    .readFileSync(abs, "utf8")
    .replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g, "")
    .trim();
}

function coveredBy(foreignBody, keeperBody) {
  const nd = (foreignBody.match(/[\u4e00-\u9fffA-Za-z0-9_./:-]{16,}/g) || [])
    .filter((s) => !/^https?:\/\//.test(s))
    .slice(0, 6);
  if (!nd.length) return foreignBody.length < 120;
  let hits = 0;
  for (const n of nd) if (keeperBody.includes(n)) hits++;
  return hits >= Math.min(2, nd.length);
}

const actions = [];
let moved = 0;
for (const [base, items] of byBase.entries()) {
  const keepers = items.filter((i) => !i.foreign);
  const losers = items.filter((i) => i.foreign);
  if (!keepers.length || !losers.length) continue;
  const best = keepers.reduce((a, b) => (bodyOf(a.abs).length >= bodyOf(b.abs).length ? a : b));
  const kb = bodyOf(best.abs);
  for (const loser of losers) {
    const fb = bodyOf(loser.abs);
    if (!coveredBy(fb, kb)) continue;
    actions.push({ base, keep: best.rel, remove: loser.rel });
    if (!DRY) {
      const dest = path.join(QUAR, loser.rel);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.renameSync(loser.abs, dest);
      moved++;
    }
  }
}

const logPath = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out",
  "foreign-quarantine-log.json"
);
fs.writeFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), dry: DRY, moved, actions }, null, 2));
console.log(DRY ? "DRY" : "APPLIED", "actions", actions.length, "moved", moved);
if (!DRY && moved) console.log("Quarantine:", QUAR);

