// 追溯葡语路径记忆来源 + 可选 quarantine
import fs from "fs";
import path from "path";
import os from "os";

const APPLY = process.argv.includes("--apply");
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const OUT = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out"
);
const BAD_DIR = /padrão|estrutura de|projeto de|notas técnicas|projeto de software/i;
const PT_WORD = /\b(Evidência|Fonte|sessão|extraído|Prova|Adicionado|segundo padrão|padrão técnico)\b/i;

const bySrc = new Map();
const bySession = new Map();
const foreign = [];
const cnSlugs = new Set();

function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && !e.name.startsWith(".")) {
      const rel = path.relative(MEM, p).replace(/\\/g, "/");
      const base = path.basename(p, ".md").toLowerCase();
      if (!BAD_DIR.test(rel)) {
        cnSlugs.add(base);
        continue;
      }
      const raw = fs.readFileSync(p, "utf8");
      const srcM = raw.match(/src=([^\s;\n]+)/);
      const curM = raw.match(/cursor session=([a-f0-9-]{36})/i);
      const dshM = raw.match(/sess(?:ão|ao)[:\s]+([a-f0-9-]{36})/i);
      const sid = curM?.[1] || dshM?.[1] || null;
      const src = srcM?.[1] || "(no src=)";
      foreign.push({ rel, abs: p, base, src, session: sid, ptBody: PT_WORD.test(raw) });
      bySrc.set(src, (bySrc.get(src) || 0) + 1);
      if (sid) bySession.set(sid, (bySession.get(sid) || 0) + 1);
    }
  }
}
walk(MEM);

const withCnSlug = foreign.filter((f) => cnSlugs.has(f.base));
const onlyForeign = foreign.filter((f) => !cnSlugs.has(f.base));

const report = {
  at: new Date().toISOString(),
  rootCause:
    "非用户葡语对话：OpenViking VLM 在批量导入（distilled/Cursor 会话 commit）时把 entities 分类目录写成葡语（padrão técnico 等），正文常混 Evidência/src=中文项目路径。",
  totalForeignPath: foreign.length,
  withChineseSameSlug: withCnSlug.length,
  onlyInForeignPath: onlyForeign.length,
  topSrc: [...bySrc.entries()].sort((a, b) => b[1] - a[1]).slice(0, 25),
  topSessions: [...bySession.entries()].sort((a, b) => b[1] - a[1]).slice(0, 20),
  sampleOnlyForeign: onlyForeign.slice(0, 30).map((f) => ({ rel: f.rel, src: f.src, session: f.session })),
};

fs.writeFileSync(path.join(OUT, "portuguese-trace.json"), JSON.stringify(report, null, 2));

const md = [
  "# 葡语路径记忆溯源",
  "",
  report.rootCause,
  "",
  `| 指标 | 数量 |`,
  `|------|------|`,
  `| 葡语/误分类路径下的 .md | **${report.totalForeignPath}** |`,
  `| 中文目录已有同名 slug（可安全 quarantine） | **${report.withChineseSameSlug}** |`,
  `| 仅存在于葡语路径（需迁移或保留中文改写） | **${report.onlyInForeignPath}** |`,
  "",
  "## 典型来源（distilled src=，非葡语会话）",
  ...report.topSrc.map(([s, n]) => `- \`${s}\` × ${n}`),
  "",
  "## 关联 Cursor/DSH session（节选）",
  ...report.topSessions.map(([s, n]) => `- \`${s}\` × ${n}`),
  "",
  "完整 JSON: portuguese-trace.json",
].join("\n");
fs.writeFileSync(path.join(OUT, "portuguese-trace.md"), md, "utf8");
console.log(JSON.stringify({ total: foreign.length, withCn: withCnSlug.length, only: onlyForeign.length }));

if (APPLY) {
  const QUAR = path.join(OUT, "dedupe-quarantine", "portuguese-path-" + new Date().toISOString().replace(/[:.]/g, "-"));
  let moved = 0;
  for (const f of withCnSlug) {
    const dest = path.join(QUAR, f.rel);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.renameSync(f.abs, dest);
    moved++;
  }
  console.log("QUARANTINED same-slug dupes", moved, QUAR);
  console.log("LEFT only-foreign", onlyForeign.length, "(manual or migrate script)");
}

// 将葡语误分类路径下的记忆迁到中文目录，修正 MEMORY_FIELDS；正文仅替换章节标签
import fs from "fs";
import path from "path";
import os from "os";

const DRY = process.argv.includes("--dry");
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const LOG = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out",
  "migrate-portuguese-log.json"
);

const BAD = /entities\/(padrão técnico|padrão de código|estrutura de código|estrutura de projeto|projeto de software|notas técnicas)/i;
const MAP = [
  [/entities\/padrão técnico/i, "entities/技术模式"],
  [/entities\/padrão de código/i, "entities/技术模式"],
  [/entities\/estrutura de código/i, "entities/代码结构"],
  [/entities\/estrutura de projeto/i, "entities/项目结构"],
  [/entities\/projeto de software/i, "entities/软件项目"],
  [/entities\/notas técnicas de frontend/i, "entities/前端技术说明"],
  [/entities\/notas técnicas/i, "entities/技术说明"],
];

const LABELS = [
  [/## Causa raiz/gi, "## 问题根因"],
  [/## Solução/gi, "## 解决方案"],
  [/## Verificação e origem/gi, "## 验证与归属"],
  [/## Descrição/gi, "## 描述"],
  [/## Fatos principais/gi, "## 关键事实"],
  [/\bEvidência:/gi, "验证证据:"],
  [/\bFonte:/gi, "来源:"],
  [/\bProva:/gi, "验证证据:"],
  [/\bArquivos:/gi, "涉及文件:"],
  [/\bProjeto:/gi, "所属项目:"],
];

const CAT_MAP = {
  "padrão técnico": "技术模式",
  "padrão de código": "技术模式",
  "Padrão técnico": "技术模式",
  "estrutura de código": "代码结构",
  "estrutura de projeto": "项目结构",
  "projeto de software": "软件项目",
  "notas técnicas de frontend": "前端技术说明",
  "notas técnicas": "技术说明",
};

function targetRel(rel) {
  let t = rel;
  for (const [re, rep] of MAP) t = t.replace(re, rep);
  return t;
}

function bodyLen(raw) {
  return raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g, "").trim().length;
}

function patchContent(raw, newRel) {
  let out = raw;
  for (const [re, rep] of LABELS) out = out.replace(re, rep);
  const m = out.match(/<!-- MEMORY_FIELDS\s*([\s\S]*?)-->/);
  if (m) {
    try {
      const j = JSON.parse(m[1].trim());
      const oldCat = j.category;
      if (oldCat && CAT_MAP[oldCat]) j.category = CAT_MAP[oldCat];
      else if (oldCat && /padrão|estrutura|projeto|notas/i.test(oldCat)) j.category = "技术模式";
      const newBlock = `<!-- MEMORY_FIELDS\n${JSON.stringify(j, null, 2)}\n-->`;
      out = out.replace(m[0], newBlock);
    } catch {}
  }
  return out;
}

const actions = [];
let moved = 0;
let skipped = 0;
const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && !e.name.startsWith(".")) files.push(p);
  }
}
walk(MEM);

for (const abs of files) {
  const rel = path.relative(MEM, abs).replace(/\\/g, "/");
  if (!BAD.test(rel)) continue;
  const destRel = targetRel(rel);
  if (destRel === rel) continue;
  const destAbs = path.join(MEM, destRel);
  const raw = fs.readFileSync(abs, "utf8");
  const patched = patchContent(raw, destRel);
  if (fs.existsSync(destAbs)) {
    const existing = fs.readFileSync(destAbs, "utf8");
    if (bodyLen(existing) >= bodyLen(patched)) {
      actions.push({ action: "quarantine_duplicate", from: rel, dest: destRel });
      if (!DRY) {
        const q = path.join(
          "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
          "out",
          "dedupe-quarantine",
          "pt-migrate-dupes",
          rel
        );
        fs.mkdirSync(path.dirname(q), { recursive: true });
        fs.renameSync(abs, q);
        skipped++;
      }
      continue;
    }
    if (!DRY) fs.unlinkSync(destAbs);
  }
  actions.push({ action: "move", from: rel, to: destRel });
  if (!DRY) {
    fs.mkdirSync(path.dirname(destAbs), { recursive: true });
    fs.writeFileSync(destAbs, patched, "utf8");
    fs.unlinkSync(abs);
    moved++;
  }
}

